# --patterns: only check that every entry still matches its source exactly once (fast;
# CI runs it so a moved line is noticed when it moves, not months later).
if len(sys.argv) > 2 and sys.argv[2] == "--patterns":
    stale = [(name, (repo / path).read_text().count(old)) for name, path, old, new, flt in M
             if (repo / path).read_text().count(old) != 1]
    for name, count in stale:
        print(f"{name:28} PATTERN NOT UNIQUE ({count})")
    print(f"{len(M) - len(stale)} of {len(M)} patterns match once")
    sys.exit(1 if stale else 0)
lo = int(sys.argv[2]) if len(sys.argv) > 2 else 0
hi = int(sys.argv[3]) if len(sys.argv) > 3 else len(M)
results = []
for name, path, old, new, flt in M[lo:hi]:
    f = repo / path
    orig = f.read_text()
    if orig.count(old) != 1:
        results.append((name, f"PATTERN NOT UNIQUE ({orig.count(old)})", []))
        continue
    try:
        f.write_text(orig.replace(old, new))
        try:
            p = subprocess.run(["swift", "test", "--filter", flt], cwd=repo, capture_output=True, text=True, timeout=600)
        except subprocess.TimeoutExpired:
            results.append((name, "TIMEOUT", []))   # hung: a test should fail, not wait
            continue
        out = p.stdout + p.stderr
        failed = sorted(set(re.findall(r"✘ Test (\w+)\(", out)))
        if "error: compile" in out.lower() or ("error:" in out and not failed and "Build complete" not in out and p.returncode != 0 and "✘" not in out):
            verdict = "COMPILE ERROR"
            failed = [l for l in out.splitlines() if "error:" in l][:2]
        else:
            crashed = "Fatal error" in out or "unexpected signal" in out
            verdict = "KILLED" if failed or crashed else "SURVIVED"
            if crashed and not failed:
                failed = ["(crashed: " + next(l for l in out.splitlines() if "Fatal error" in l or "unexpected signal" in l)[:80] + ")"]
        results.append((name, verdict, failed))
    finally:
        f.write_text(orig)
for name, verdict, failed in results:
    print(f"{name:28} {verdict:10} {', '.join(failed)}")
